//! Podcast/radio reference: explicit fetch/play/metadata, one shared host player.
use crate::{*,serde_json::{json,Value}};
pub fn controller(input:Value)->Value{let mut s=input["state"].clone();if !s.is_object(){s=json!({"feed":"","stream":"","metadata":"","episodes":[],"status":"Configure URLs within the app's signed origins","radio":null,"playing":false});}let e=&input["event"];let a=e["action"].as_str().unwrap_or("");let v=&e["reply"]["value"];let ok=e["reply"]["ok"]==true;let mut req=Value::Null;
match a{"listen.feed"|"listen.stream"|"listen.metadata"=>{s[&a[7..]]=e["value"].clone();if a=="listen.stream"{s["radio"]=Value::Null;}},"listen.fetch"=>{req=podcasts::fetch(s["feed"].as_str().unwrap_or(""),"listen.fetched");s["status"]=json!("Loading podcast feed…");},"listen.fetched" if ok=>match podcasts::parse(v,"listen.parsed"){Ok(r)=>req=r,Err(err)=>s["status"]=json!(err)},"listen.parsed" if ok=>{s["episodes"]=v["episodes"].clone();s["status"]=json!(format!("{} episodes",v["episodes"].as_array().map_or(0,Vec::len)));},"listen.radio.play"=>{req=radio::play(s["stream"].as_str().unwrap_or(""),"Selected radio stream","listen.played");},"listen.radio.metadata"=>{req=radio::fetch(s["metadata"].as_str().unwrap_or(""),"listen.radio.loaded");},"listen.radio.loaded" if ok=>match radio::metadata(v,s["stream"].as_str().unwrap_or("")){Ok(data)=>{s["radio"]=data;s["status"]=json!("Metadata at last manual refresh");},Err(err)=>{s["radio"]=Value::Null;s["status"]=json!(err);}},"listen.played" if ok=>{s["playing"]=json!(true);s["status"]=json!("Playback handed to shared player");},_ if a.starts_with("episode.")=>{if let Some(episode)=a[8..].parse::<usize>().ok().and_then(|i|s["episodes"].as_array().and_then(|v|v.get(i))){match podcasts::play(episode,"listen.played"){Ok(r)=>req=r,Err(err)=>s["status"]=json!(err)}}},_=>{}}
if e["reply"]["ok"]==false{s["status"]=json!("Operation unavailable or access denied; previous episodes retained");if a=="listen.radio.loaded"{s["radio"]=Value::Null;}}
let mut nodes=vec![field("listen.feed","Podcast RSS2 HTTPS URL",s["feed"].as_str().unwrap_or("")),button("listen.fetch","Load podcast episodes"),field("listen.stream","Selected radio HTTPS stream",s["stream"].as_str().unwrap_or("")),button("listen.radio.play","Play selected radio"),field("listen.metadata","Icecast status HTTPS URL",s["metadata"].as_str().unwrap_or("")),button("listen.radio.metadata","Refresh radio title"),label("listen.song",s["radio"]["title"].as_str().filter(|s|!s.is_empty()).unwrap_or("Radio title unavailable")),label("listen.status",s["status"].as_str().unwrap_or(""))];if s["playing"]==true{nodes.push(media::player("listen.player"));}for(i,episode)in s["episodes"].as_array().into_iter().flatten().take(40).enumerate(){nodes.push(record(&format!("episode.{i}"),episode["title"].as_str().unwrap_or("Episode"),"Play selected episode"));}for n in &mut nodes{if n["kind"]=="field"{n["limit"]=json!(512);}}Screen::new("Listening",s).body(nodes).scrollable().effect(req).finish()}
